def f(m, n):
    if m == 0 or n == 0:
        return 1
    return f(m - 1, n) + f(m - 1, n - 1) + f(m, n - 1)

print(f(2, 5))

def f(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 8
    return f(n - 1) + f(n - 3)

print(f(10))

def f(a):
    if a <= 0:
        return 0
    return (a % 7) * f(a // 7) + a % 7

print(f([빈 칸]))

def p(a, b):
    if b == 0:
        return a
    return p(b, a % b)

print(p(132, 88))
